// **📖 Related Article:** [Deribit Block RFQ API walkthrough](https://docs.deribit.com/articles/block-rfq-api-walkthrough)
//
// **Scope:** `block_rfq:read_write`
//
// [Try in API console](https://test.deribit.com/api_console?method=%2Fprivate%2Faccept_block_rfq)
func (c *Client) PrivateAcceptBlockRfq(ctx context.Context, params *PrivateAcceptBlockRfqParams, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewPrivateAcceptBlockRfqRequest(c.Server, params)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

